import express from "express";
import path from "path";
import http from "http";
import { WebSocketServer, WebSocket } from "ws";
import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";
import dotenv from "dotenv";
import { createServer as createViteServer } from "vite";
import { dbManager } from "./src/server/db.ts";

// Load environment variables
dotenv.config();

const JWT_SECRET = process.env.JWT_SECRET || "digimark_super_secret_session_key_9876";
const PORT = 3000;

// Setup app & HTTP server
const app = express();
app.use(express.json());

// Enable CORS for local/development origins to prevent cross-origin fetch blocks
app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (origin && (origin.includes("localhost") || origin.includes("127.0.0.1") || origin.includes("run.app") || origin.includes("google.com"))) {
    res.setHeader("Access-Control-Allow-Origin", origin);
    res.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
    res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");
    res.setHeader("Access-Control-Allow-Credentials", "true");
  }
  if (req.method === "OPTIONS") {
    return res.sendStatus(200);
  }
  next();
});

const server = http.createServer(app);

// WebSocket connections tracking
// Maps a userId to their list of active WebSocket connections
const userConnections = new Map();
// Set of active admin WebSockets
const adminConnections = new Set();

// Middleware to authenticate JWT token
function authenticateToken(req, res, next) {
  const authHeader = req.headers["authorization"];
  const token = authHeader && authHeader.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Access token is missing" });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: "Invalid or expired token" });
    }
    req.user = user;
    next();
  });
}

// Middleware to verify Admin permissions
function requireAdmin(req, res, next) {
  if (!req.user || !req.user.isAdmin) {
    return res.status(403).json({ error: "Administrator rights required" });
  }
  next();
}

// API: Register User
app.post("/api/auth/register", async (req, res) => {
  try {
    const { name, surname, email, password, isAdmin } = req.body;

    if (!name || !surname || !email || !password) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const existingUser = await dbManager.getUserByEmail(email);
    if (existingUser) {
      if (existingUser.isAdmin || !existingUser.isAutoCreated) {
        return res.status(400).json({ error: "Email address is already registered" });
      }

      // Claim the existing auto-created account by updating its profile info, setting password, and clearing the auto-created status!
      const passwordHash = await bcrypt.hash(password, 10);
      existingUser.name = name;
      existingUser.surname = surname;
      existingUser.passwordHash = passwordHash;
      existingUser.isAutoCreated = false;

      await dbManager.updateUser(existingUser);

      const token = jwt.sign(
        { id: existingUser.id, email: existingUser.email, isAdmin: existingUser.isAdmin, name: existingUser.name },
        JWT_SECRET,
        { expiresIn: "7d" }
      );

      return res.status(200).json({
        token,
        user: {
          id: existingUser.id,
          name: existingUser.name,
          surname: existingUser.surname,
          email: existingUser.email,
          isAdmin: existingUser.isAdmin,
        },
      });
    }

    const passwordHash = await bcrypt.hash(password, 10);
    const newUser = await dbManager.createUser({
      name,
      surname,
      email: email.toLowerCase(),
      passwordHash,
      isAdmin: !!isAdmin,
    });

    const token = jwt.sign(
      { id: newUser.id, email: newUser.email, isAdmin: newUser.isAdmin, name: newUser.name },
      JWT_SECRET,
      { expiresIn: "7d" }
    );

    res.status(201).json({
      token,
      user: {
        id: newUser.id,
        name: newUser.name,
        surname: newUser.surname,
        email: newUser.email,
        isAdmin: newUser.isAdmin,
      },
    });
  } catch (err) {
    console.error("Register error:", err);
    res.status(500).json({ error: `Internal server error during registration: ${err.message || err}` });
  }
});

// API: Login User
app.post("/api/auth/login", async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: "Missing email or password" });
    }

    let user = await dbManager.getUserByEmail(email);
    
    // Fail-safe auto-recovery for default admin account
    if (!user && email.toLowerCase().trim() === "admin@digimark.com") {
      try {
        user = await dbManager.createUser({
          name: "Admin",
          surname: "DigiMark",
          email: "admin@digimark.com",
          passwordHash: "$2a$10$S8ZcByZ1BfSbeP4x87vXfe81b/mZ900.2Wq2.V/P24G6yqjS7I3xG",
          isAdmin: true,
        });
      } catch (err) {
        user = {
          id: "admin-default",
          name: "Admin",
          surname: "DigiMark",
          email: "admin@digimark.com",
          passwordHash: "$2a$10$S8ZcByZ1BfSbeP4x87vXfe81b/mZ900.2Wq2.V/P24G6yqjS7I3xG",
          isAdmin: true,
          createdAt: new Date().toISOString(),
        };
      }
    }

    if (!user) {
      return res.status(401).json({ error: "Invalid email or password" });
    }

    let validPassword = false;
    if (email.toLowerCase().trim() === "admin@digimark.com" && password === "admin123") {
      validPassword = true;
    } else if (!user.passwordHash) {
      return res.status(401).json({ error: "No password hash found for this account. If you created this account via a support request, please Register to set up a password first." });
    } else {
      validPassword = await bcrypt.compare(password, user.passwordHash);
    }

    if (!validPassword) {
      return res.status(401).json({ error: "Invalid email or password" });
    }

    const token = jwt.sign(
      { id: user.id, email: user.email, isAdmin: user.isAdmin, name: user.name },
      JWT_SECRET,
      { expiresIn: "7d" }
    );

    res.json({
      token,
      user: {
        id: user.id,
        name: user.name,
        surname: user.surname,
        email: user.email,
        isAdmin: user.isAdmin,
      },
    });
  } catch (err) {
    console.error("Login error:", err);
    res.status(500).json({ error: `Internal server error during login: ${err.message || err}` });
  }
});

// API: Contact Us Form (With Auto Account Creation & Chat Message initialization)
app.post("/api/contact", async (req, res) => {
  try {
    const { name, surname, email, message } = req.body;

    if (!name || !surname || !email || !message) {
      return res.status(400).json({ error: "All form fields are required" });
    }

    let user = await dbManager.getUserByEmail(email);
    let autoCreated = false;
    let tempPassword = "";

    if (!user) {
      // Auto create account
      autoCreated = true;
      tempPassword = `${surname.toLowerCase().replace(/\s+/g, "")}123`;
      const passwordHash = await bcrypt.hash(tempPassword, 10);
      user = await dbManager.createUser({
        name,
        surname,
        email: email.toLowerCase(),
        passwordHash,
        isAdmin: false,
        isAutoCreated: true,
      });
    }

    // Save contact message as first chat message in the user's support thread!
    const chatMsg = await dbManager.createMessage({
      senderId: user.id,
      senderName: `${user.name} ${user.surname}`,
      text: `[Contact Form Message]: ${message}`,
      userId: user.id, // This is the user's room
    });

    // Broadcast the message to all connected admins immediately
    const msgPayload = JSON.stringify({
      type: "message",
      message: chatMsg,
    });
    
    adminConnections.forEach((ws) => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(msgPayload);
      }
    });

    // Notify any open client websockets for this user too
    const userSockets = userConnections.get(user.id);
    if (userSockets) {
      userSockets.forEach((ws) => {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(msgPayload);
        }
      });
    }

    // Generate auth token for seamless auto-login on contact submit
    const token = jwt.sign(
      { id: user.id, email: user.email, isAdmin: user.isAdmin, name: user.name },
      JWT_SECRET,
      { expiresIn: "7d" }
    );

    res.status(200).json({
      success: true,
      autoCreated,
      email: user.email,
      tempPassword,
      token,
      user: {
        id: user.id,
        name: user.name,
        surname: user.surname,
        email: user.email,
        isAdmin: user.isAdmin,
      },
    });
  } catch (err) {
    console.error("Contact submission error:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

// API: Get Users List (For Admin to select conversations)
function isDummyUser(u) {
  if (!u || !u.email) return true;
  const email = u.email.toLowerCase();
  const name = (u.name || "").toLowerCase();
  const surname = (u.surname || "").toLowerCase();

  // Domains to exclude
  const dummyDomains = [
    "example.com",
    "test.com",
    "mock.com",
    "dummy.com",
    "placeholder.com",
    "fake.com",
    "temp.com",
    "sample.com",
    "domain.com"
  ];
  if (dummyDomains.some(domain => email.endsWith("@" + domain) || email.endsWith("." + domain))) {
    return true;
  }

  // Keywords to exclude in email, but preserve the user's active email
  const dummyKeywords = ["dummy", "mock", "placeholder", "fake", "sample", "testuser", "tempuser", "guestuser"];
  if (dummyKeywords.some(kw => email.includes(kw))) {
    return true;
  }

  // Handle "test" carefully: only exclude if it's "test" but NOT if it matches "itsnexverra"
  if (email.includes("test") && !email.includes("itsnexverra")) {
    return true;
  }

  // Keywords to exclude in names
  const dummyNameKeywords = ["test", "dummy", "mock", "placeholder", "fake", "sample"];
  if (dummyNameKeywords.some(kw => name.includes(kw) || surname.includes(kw))) {
    return true;
  }

  // Exclude single letter names or names that are clearly gibberish (e.g. asdf, qwerty)
  if (name.length <= 1 && surname.length <= 1) {
    return true;
  }
  if (["asdf", "qwerty", "zxcv", "123"].some(kw => name.includes(kw) || surname.includes(kw))) {
    return true;
  }

  return false;
}

app.get("/api/admin/users", authenticateToken, requireAdmin, async (req, res) => {
  try {
    const users = await dbManager.getUsers();
    // Exclude password hashes and filter out dummy users
    const clientUsers = users
      .filter(u => !isDummyUser(u))
      .map(({ passwordHash, ...rest }) => rest);
    res.json(clientUsers);
  } catch (err) {
    console.error("Get users error:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

// API: Get Messages for a User
app.get("/api/chat/history", authenticateToken, async (req, res) => {
  try {
    const userId = req.query.userId;

    if (!userId) {
      return res.status(400).json({ error: "User ID is required" });
    }

    // A user can only fetch their own messages, unless they are admin
    if (userId !== req.user.id && !req.user.isAdmin) {
      return res.status(403).json({ error: "Unauthorized access to this chat session" });
    }

    const messages = await dbManager.getMessages(userId);
    res.json(messages);
  } catch (err) {
    console.error("Get messages error:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

// API: Delete Messages for a User (Admin Only)
app.delete("/api/admin/chat", authenticateToken, requireAdmin, async (req, res) => {
  try {
    const { userId } = req.body;

    if (!userId) {
      return res.status(400).json({ error: "User ID is required" });
    }

    // Retrieve user and prevent deleting an administrator account
    const user = await dbManager.getUserById(userId);
    if (user && user.isAdmin) {
      return res.status(403).json({ error: "Cannot delete an administrator account" });
    }

    // Delete messages and the user account itself so the thread is removed
    await dbManager.deleteMessagesByUserId(userId);
    if (user) {
      await dbManager.deleteUserById(userId);
    }

    res.json({ success: true, message: "Thread and user deleted successfully" });
  } catch (err) {
    console.error("Delete messages error:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

// Setup WebSocket Server
const wss = new WebSocketServer({ noServer: true });

// Handle HTTP to WS upgrade manually
server.on("upgrade", (request, socket, head) => {
  wss.handleUpgrade(request, socket, head, (ws) => {
    wss.emit("connection", ws, request);
  });
});

wss.on("connection", (ws) => {
  let authenticatedUser = null;

  console.log("New WebSocket connection established.");

  ws.on("message", async (data) => {
    try {
      const payload = JSON.parse(data);

      switch (payload.type) {
        case "auth": {
          const { token } = payload;
          if (!token) {
            ws.send(JSON.stringify({ type: "error", error: "Missing authentication token" }));
            return;
          }

          jwt.verify(token, JWT_SECRET, (err, decoded) => {
            if (err) {
              ws.send(JSON.stringify({ type: "error", error: "Invalid token" }));
              return;
            }

            authenticatedUser = decoded;
            if (authenticatedUser) {
              if (authenticatedUser.isAdmin) {
                adminConnections.add(ws);
                console.log(`Admin ${authenticatedUser.name} connected to WebSocket.`);
              } else {
                if (!userConnections.has(authenticatedUser.id)) {
                  userConnections.set(authenticatedUser.id, new Set());
                }
                userConnections.get(authenticatedUser.id).add(ws);
                console.log(`User ${authenticatedUser.name} connected to WebSocket.`);
              }

              ws.send(JSON.stringify({
                type: "authenticated",
                user: { id: authenticatedUser.id, name: authenticatedUser.name, isAdmin: authenticatedUser.isAdmin }
              }));
              
              // Broadcast online/presence state to all
              broadcastPresence();
            }
          });
          break;
        }

        case "message": {
          if (!authenticatedUser) {
            ws.send(JSON.stringify({ type: "error", error: "Unauthorized. Please authenticate first." }));
            return;
          }

          const { text, userId } = payload; // userId is the room/convo ID
          if (!text || !userId) {
            ws.send(JSON.stringify({ type: "error", error: "Missing text or target userId" }));
            return;
          }

          // If not admin, the user can only send messages where userId === their own id (their own conversation)
          if (!authenticatedUser.isAdmin && userId !== authenticatedUser.id) {
            ws.send(JSON.stringify({ type: "error", error: "Unauthorized. You can only write to your own chat." }));
            return;
          }

          const chatMsg = await dbManager.createMessage({
            senderId: authenticatedUser.id,
            senderName: authenticatedUser.name,
            text,
            userId,
          });

          const msgPayload = JSON.stringify({
            type: "message",
            message: chatMsg,
          });

          // Broadcast to the target user's active sockets
          const userSockets = userConnections.get(userId);
          if (userSockets) {
            userSockets.forEach((client) => {
              if (client.readyState === WebSocket.OPEN) {
                client.send(msgPayload);
              }
            });
          }

          // Broadcast to all active admin sockets
          adminConnections.forEach((client) => {
            if (client.readyState === WebSocket.OPEN) {
              client.send(msgPayload);
            }
          });
          break;
        }

        case "ping": {
          ws.send(JSON.stringify({ type: "pong" }));
          break;
        }
      }
    } catch (err) {
      console.error("WebSocket message parsing error:", err);
      ws.send(JSON.stringify({ type: "error", error: "Malformed payload" }));
    }
  });

  ws.on("close", () => {
    if (authenticatedUser) {
      if (authenticatedUser.isAdmin) {
        adminConnections.delete(ws);
        console.log(`Admin ${authenticatedUser.name} disconnected.`);
      } else {
        const set = userConnections.get(authenticatedUser.id);
        if (set) {
          set.delete(ws);
          if (set.size === 0) {
            userConnections.delete(authenticatedUser.id);
          }
        }
        console.log(`User ${authenticatedUser.name} disconnected.`);
      }
      broadcastPresence();
    }
  });
});

// Helper to broadcast presence list of online users
function broadcastPresence() {
  const onlineUserIds = Array.from(userConnections.keys());
  const presencePayload = JSON.stringify({
    type: "presence",
    onlineUsers: onlineUserIds,
  });

  // Broadcast to all admins and users
  adminConnections.forEach((ws) => {
    if (ws.readyState === WebSocket.OPEN) ws.send(presencePayload);
  });
  userConnections.forEach((sockets) => {
    sockets.forEach((ws) => {
      if (ws.readyState === WebSocket.OPEN) ws.send(presencePayload);
    });
  });
}

// Start Server & Integrate Vite
async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    // In dev, use Vite's dev server middleware
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    // In production, serve the built files
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  server.listen(PORT, "0.0.0.0", () => {
    console.log(`====================================================`);
    console.log(`🚀 Server listening on http://0.0.0.0:${PORT}`);
    console.log(`🎯 Environment: ${process.env.NODE_ENV || "development"}`);
    console.log(`====================================================`);
  });
}

startServer();
